//! `index_files` takes paths straight from its callers (the file watcher,
//! `reindex_damaged_files`), so it must apply the same filters as the scan,
//! and generated files must not look "new" on every sync.
//!
//! Run: cargo test -p ax-extraction --test index_files_filters

use ax_db::queries::QueryBuilder;
use ax_db::Database;
use ax_extraction::orchestrator::{ExtractionOrchestrator, IndexOptions};

struct Fixture {
    root: std::path::PathBuf,
    db: std::path::PathBuf,
}

impl Fixture {
    fn new(name: &str) -> Self {
        let base = std::env::temp_dir().join(format!(
            "ax-index-files-{name}-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .map(|d| d.as_nanos())
                .unwrap_or(0)
        ));
        std::fs::create_dir_all(&base).expect("create fixture dir");
        Self {
            db: base.join("ax.db"),
            root: base,
        }
    }

    fn write(&self, rel: &str, body: &str) {
        let path = self.root.join(rel);
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent).expect("create parent");
        }
        std::fs::write(path, body).expect("write fixture file");
    }
}

impl Drop for Fixture {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.root);
    }
}

async fn file_paths(queries: &QueryBuilder) -> Vec<String> {
    let mut paths: Vec<String> = queries
        .get_all_files()
        .await
        .expect("files")
        .into_iter()
        .map(|f| f.path)
        .collect();
    paths.sort();
    paths
}

#[tokio::test]
async fn index_files_applies_the_scan_filters_before_reading() {
    let fx = Fixture::new("filters");
    fx.write("src/keep.rs", "pub fn keep() -> u32 {\n    7\n}\n");
    fx.write("node_modules/x/index.js", "export function dep() {}\n");
    fx.write("gen/out.rs", "pub fn excluded() {}\n");
    fx.write("bin/blob.o", "\u{1}ELF not really code\n");

    let db = Database::open(&fx.db).await.expect("open db");
    let queries = QueryBuilder::new(db.pool().clone());
    let orchestrator = ExtractionOrchestrator::new(fx.root.clone());
    let opts = IndexOptions {
        exclude: vec!["gen/".to_string()],
        ..IndexOptions::default()
    };

    let paths: Vec<String> = [
        "src/keep.rs",
        "node_modules/x/index.js",
        "gen/out.rs",
        "bin/blob.o",
    ]
    .iter()
    .map(|s| s.to_string())
    .collect();
    let result = orchestrator
        .index_files(&queries, &paths, &opts, None)
        .await
        .expect("index_files");

    assert_eq!(
        file_paths(&queries).await,
        vec!["src/keep.rs".to_string()],
        "only the path the scan would keep gets a files row"
    );
    assert_eq!(result.files_indexed, 1);
    let scanned: Vec<String> = orchestrator
        .scan_files(&opts)
        .await
        .expect("scan")
        .into_iter()
        .map(|p| {
            p.strip_prefix(&fx.root)
                .unwrap()
                .to_string_lossy()
                .replace('\\', "/")
        })
        .collect();
    assert_eq!(
        scanned,
        vec!["src/keep.rs".to_string()],
        "scan and index_files agree"
    );
    assert!(queries
        .get_nodes_by_file("gen/out.rs")
        .await
        .expect("nodes")
        .is_empty());
}

#[tokio::test]
async fn generated_file_is_not_reindexed_on_every_sync() {
    let fx = Fixture::new("generated");
    fx.write("src/keep.rs", "pub fn keep() -> u32 {\n    7\n}\n");
    fx.write(
        "src/proto.rs",
        "// Code generated by protoc. DO NOT EDIT.\npub fn generated() {}\n",
    );

    let db = Database::open(&fx.db).await.expect("open db");
    let queries = QueryBuilder::new(db.pool().clone());
    let orchestrator = ExtractionOrchestrator::new(fx.root.clone());
    let opts = IndexOptions::default();

    orchestrator
        .index_all(&queries, &opts, None)
        .await
        .expect("index_all");
    assert!(queries
        .get_nodes_by_file("src/proto.rs")
        .await
        .expect("nodes")
        .is_empty());

    let first = orchestrator
        .sync_changed(&queries, &opts, None)
        .await
        .expect("sync");
    assert!(
        first.affected_files.is_empty(),
        "an unchanged generated file must not count as changed: {:?}",
        first.affected_files
    );
    let second = orchestrator
        .sync_changed(&queries, &opts, None)
        .await
        .expect("sync");
    assert!(
        second.affected_files.is_empty(),
        "{:?}",
        second.affected_files
    );
}

#[tokio::test]
async fn file_that_becomes_generated_loses_its_old_nodes() {
    let fx = Fixture::new("becomes-generated");
    fx.write("src/api.rs", "pub fn handwritten() {}\n");

    let db = Database::open(&fx.db).await.expect("open db");
    let queries = QueryBuilder::new(db.pool().clone());
    let orchestrator = ExtractionOrchestrator::new(fx.root.clone());
    let opts = IndexOptions::default();

    orchestrator
        .index_all(&queries, &opts, None)
        .await
        .expect("index_all");
    assert!(queries
        .get_nodes_by_file("src/api.rs")
        .await
        .expect("nodes")
        .iter()
        .any(|n| n.name == "handwritten"));

    fx.write(
        "src/api.rs",
        "// Code generated by a tool. DO NOT EDIT.\npub fn regenerated_with_more_text() {}\n",
    );
    orchestrator
        .index_files(&queries, &["src/api.rs".to_string()], &opts, None)
        .await
        .expect("index_files");
    let names: Vec<String> = queries
        .get_nodes_by_file("src/api.rs")
        .await
        .expect("nodes")
        .into_iter()
        .map(|n| n.name)
        .collect();
    assert!(
        !names.iter().any(|n| n == "handwritten"),
        "nodes of the hand-written version must be cleared: {names:?}"
    );
}

/// A UTF-8 BOM followed by invalid UTF-8: `read_text_file` refuses it.
fn write_undecodable(fx: &Fixture, rel: &str) {
    let mut bytes = vec![0xEF, 0xBB, 0xBF];
    bytes.extend_from_slice(b"pub fn broken() {}\n// ");
    bytes.extend_from_slice(&[0xC3, 0x28, b'\n']);
    let path = fx.root.join(rel);
    std::fs::create_dir_all(path.parent().unwrap()).expect("create parent");
    std::fs::write(path, bytes).expect("write fixture file");
}

#[tokio::test]
async fn one_unreadable_file_does_not_fail_the_batch() {
    let fx = Fixture::new("unreadable");
    fx.write("src/a.rs", "pub fn alpha() {}\n");
    write_undecodable(&fx, "src/bad.rs");
    fx.write("src/z.rs", "pub fn zulu() {}\n");
    assert!(ax_utils::read_text_file(&fx.root.join("src/bad.rs")).is_err());

    let db = Database::open(&fx.db).await.expect("open db");
    let queries = QueryBuilder::new(db.pool().clone());
    let orchestrator = ExtractionOrchestrator::new(fx.root.clone());
    let opts = IndexOptions::default();

    let paths: Vec<String> = ["src/a.rs", "src/bad.rs", "src/z.rs"]
        .iter()
        .map(|s| s.to_string())
        .collect();
    let result = orchestrator
        .index_files(&queries, &paths, &opts, None)
        .await
        .expect("an unreadable file is skipped, not fatal");
    assert_eq!(result.files_indexed, 2);
    assert_eq!(
        file_paths(&queries).await,
        vec!["src/a.rs".to_string(), "src/z.rs".to_string()]
    );
}

#[tokio::test]
async fn one_unreadable_file_does_not_fail_a_full_index() {
    let fx = Fixture::new("unreadable-all");
    fx.write("src/a.rs", "pub fn alpha() {}\n");
    write_undecodable(&fx, "src/bad.rs");

    let db = Database::open(&fx.db).await.expect("open db");
    let queries = QueryBuilder::new(db.pool().clone());
    let orchestrator = ExtractionOrchestrator::new(fx.root.clone());

    orchestrator
        .index_all(&queries, &IndexOptions::default(), None)
        .await
        .expect("an unreadable file is skipped, not fatal");
    assert_eq!(file_paths(&queries).await, vec!["src/a.rs".to_string()]);
}
